"""Local video and live-decision review; no web server needed."""
import json
from pathlib import Path
B=Path(__file__).resolve().parents[1];R=B/'runs/gpt_walk_revo2_001'
rows=[]
for p in sorted(R.glob('decision_[0-9][0-9][0-9].json')):
 d=json.loads(p.read_text());o=json.loads((R/f'observation_{d["observation_id"]:03d}.json').read_text());rows.append({'time':o['step']*.02,'action':d['action'],'goal':d.get('goal',{}),'reason':d['reason'],'root':o['robot_root_pos'],'contact':o['grasp_information']['metrics']['object_hand_normal_force_N'],'clearance':o['grasp_information']['metrics']['whole_object_clearance_m']})
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>Revo 2 · 走近与GPT在线抓取</title><style>body{font:16px system-ui;background:#111b26;color:#e3ecf6;max-width:1280px;margin:28px auto;padding:20px}p{line-height:1.7;color:#c6d3e1}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}section{background:#1c2b3d;padding:18px;border-radius:12px;margin:18px 0}video,img{width:100%;border-radius:8px}pre{white-space:pre-wrap;line-height:1.6}a{color:#8acaff}h1{font-size:28px}button{padding:8px 20px;margin:10px}</style>
<h1>G1＋强脑 Revo 2 · GPT在线路点更新</h1><p>窗洞缩至1.30×0.90米，窗台抬高10厘米，开角45°；起点后退40厘米。左右五指手为Revo 2物理模型，SONIC planner＋IK＋SONIC执行。GPT读取图像、本体与特权信息逐段更新；等待判断时暂停物理时间，视频时间为连续仿真时间。</p>
<section><h2>第一人称与腕部</h2><div class="grid"><div>头部第一视角<video id="head" controls preload="metadata" src="runs/gpt_walk_revo2_001/head.mp4"></video></div><div>右腕视角<video id="wrist" muted preload="metadata" src="runs/gpt_walk_revo2_001/right_wrist.mp4"></video></div></div><pre id="decision"></pre><small>显示最近一次GPT决策。接触力和离桌高度为该反馈点的实测量，不是未来预测。</small></section>
<section><h2>第三视角：行走与五指手</h2><video controls preload="metadata" src="runs/gpt_walk_revo2_001/000000.mp4"></video></section>
<div class="grid"><section><h2>缩小后的窗户</h2><img src="assets/preview_overview.png"></section><section><h2>报告与记录</h2><p><a href="REPORT.md">总报告</a> · <a href="README.md">复现说明</a></p><p><a href="runs/gpt_walk_revo2_001/REPORT.md">Revo 2报告</a> · <a href="runs/gpt_walk_revo2_001/validation.json">传感器/视频验证</a> · <a href="runs/gpt_walk_revo2_001/hand_validation.json">物理连接/联动验证</a></p><p><a href="runs/gpt_walk_dex3_001/REPORT.md">原三指手基线报告</a> · <a href="runs/gpt_walk_dex3_001/head.mp4">原手第一视角</a></p><p>旧手保留无碰撞、极小质量的兼容关节。Revo 2转动惯量有稳定仿真用的估计项，尚未实物标定；详见报告。</p></section></div>
<script>const D=DECISIONS;const h=document.querySelector('#head'),w=document.querySelector('#wrist');function update(){let d=D.filter(x=>x.time<=h.currentTime).at(-1)||D[0];document.querySelector('#decision').textContent=`反馈 ${d.time.toFixed(2)} 秒 | ${d.action}\n目标 ${JSON.stringify(d.goal)}\n依据 ${d.reason}\n骨盆 [${d.root.map(x=>x.toFixed(3)).join(', ')}] m | 手部接触 ${d.contact.toFixed(2)} N | 整物离桌 ${(100*d.clearance).toFixed(2)} cm`;if(Math.abs(w.currentTime-h.currentTime)>.07)w.currentTime=h.currentTime;}h.onplay=()=>{w.currentTime=h.currentTime;w.play()};h.onpause=()=>w.pause();h.onseeked=()=>{w.currentTime=h.currentTime;update()};h.ontimeupdate=update;h.onratechange=()=>w.playbackRate=h.playbackRate;update();</script></html>'''
(B/'index.html').write_text(html.replace('DECISIONS',json.dumps(rows,ensure_ascii=False)))
print(B/'index.html')
